!function(t){function r(r){for(var p,a,i=r[0],o=r[1],u=r[2],k=0,g=[];k<i.length;k++)a=i[k],Object.prototype.hasOwnProperty.call(e,a)&&e[a]&&g.push(e[a][0]),e[a]=0;for(p in o)Object.prototype.hasOwnProperty.call(o,p)&&(t[p]=o[p]);for(c&&c(r);g.length;)g.shift()();return n.push.apply(n,u||[]),m()}function m(){for(var t,r=0;r<n.length;r++){for(var m,a=n[r],i=!0,o=1;o<a.length;o++)m=a[o],0!==e[m]&&(i=!1);i&&(n.splice(r--,1),t=p(p.s=a[0]))}return t}function p(r){if(a[r])return a[r].exports;var m=a[r]={i:r,l:!1,exports:{}};return t[r].call(m.exports,m,m.exports,p),m.l=!0,m.exports}var a={},e={6:0},n=[];p.m=t,p.c=a,p.d=function(t,r,m){p.o(t,r)||Object.defineProperty(t,r,{enumerable:!0,get:m})},p.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},p.t=function(t,r){if(1&r&&(t=p(t)),8&r)return t;if(4&r&&"object"==typeof t&&t&&t.__esModule)return t;var m=Object.create(null);if(p.r(m),Object.defineProperty(m,"default",{enumerable:!0,value:t}),2&r&&"string"!=typeof t)for(var a in t)p.d(m,a,function(r){return t[r]}.bind(null,a));return m},p.n=function(t){var r=t&&t.__esModule?function(){return t.default}:function(){return t};return p.d(r,"a",r),r},p.o=function(t,r){return Object.prototype.hasOwnProperty.call(t,r)},p.p="";var i=window.webpackJsonp=window.webpackJsonp||[],o=i.push.bind(i);i.push=r,i=i.slice();for(var u=0;u<i.length;u++)r(i[u]);var c=o;n.push([29,0]),m()}({29:function(t,r,m){"use strict";m.r(r);var p=m(0);Object(p.a)("uk","army",m(30),m(1))},30:function(t){t.exports=JSON.parse('{"category":[{"name":"英国","link":"uk_shortcut"},{"name":"陆战武器","link":"uk_army"},{"name":"坦克","link":"uk_army#uk_army_tank"}],"model":"A27L/A30/A34巡航坦克","description":"<h6>综述：</h6><p>在“克伦蒂尔”巡航坦克出世前后，英国分别研制了A27L“半人马座”（或称“人头马”）巡航坦克、A30“挑战者”巡航坦克和A34“慧星”巡航坦克。其中A27L“半人马座”巡航坦克可以说是“十字军”巡航坦克向“克伦威尔”巡航坦克的过渡产品，它于1942年问世，1943年在配上“流星”发动机后则变为“克伦威尔”巡航坦克了。A30“挑战者”巡航坦克在1943年开始生产，它是由“克伦威尔”巡航坦克改装而成，而A34“慧星”巡航坦克也是一种对“克伦威尔”巡航坦克提升改造而成的坦克，它在1944年12月才装备英军装甲部队，它是一种在装甲和火力上基本上能与德军重型坦克对抗的坦克，也是英国最后一种巡航坦克。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}A27L“半人马座”巡航坦克（1943年）{{image}}imgs/uk/army/uk_army_tankcx_11.jpg{{text}}A27L“半人马座”巡航坦克<br>1945年春天，苏格兰地区，隶属英军第16独立装甲旅第5 装甲团的一辆A27L“半人马座”巡航坦克。{{image}}imgs/uk/army/uk_army_tankcx_12.jpg{{text}}A27L“半人马座”巡航坦克{{image}}imgs/uk/army/uk_army_tankcx_13.jpg","description":"<h6>A27L“半人马座”巡航坦克</h6><p>作为“克伦威尔”的过渡坦克，除了所安装的发动机不相同外，其余结构与“克伦威尔”巡航坦克基本相同，但车速明显比后来装了“流星”发动机的“克伦威尔”巡航坦克低很多。早期的“半人马座”巡航坦克安装是6磅火炮，后期Ⅱ型改装了95mm榴弹炮。</p><p>坦克参数为：</p><p>车长：6.35m，车宽：2.91m, 车高：2.49m，车重：约29.0t，乘员：5人；</p><p>最高车速：43km/h，最大行程：265km；</p><p>装甲厚度：20-76mm；</p><p>主要武器装备：一门95mm榴弹炮。</p><p>辅助武器有2挺7.92mm机枪。</p>","caption":""},{"image":"{{text}}A30“挑战者”巡航坦克<br>1944年11月，荷兰战场，隶属英军第1装甲师第10马步枪团的一辆A30“挑战者”巡航坦克。{{image}}imgs/uk/army/uk_army_tankcx_21.jpg{{text}}A30“挑战者”巡航坦克{{image}}imgs/uk/army/uk_army_tankcx_22.jpg{{text}}A30“挑战者”巡航坦克{{image}}imgs/uk/army/uk_army_tankcx_23.jpg","description":"<h6>A30“挑战者”巡航坦克</h6><p>“挑战者”巡航坦克在 1942年5月就开始设计，1943年开始生产，计划生产200辆，但一直到1944年才交货（有资料说只完成了36辆）。</p><p>“挑战者”巡航坦克有6个负重轮（比“克伦威尔”增加了1个），因此车体增长了1.8m；由于安装了17磅（76.2mm口径）的火炮，其炮塔显得更大；该坦克正面装甲增至102mm，车重超过30t，因此车速大大降低。</p><p>坦克参数为：</p><p>车长：8.15m，车宽：2.9m, 车高：2.78m，车重：约33.0t，乘员：5人；</p><p>最高车速：24km/h，最大行程：193km；</p><p>装甲厚度：20-102mm；</p><p>主要武器装备：一门17磅（76.2mm口径）火炮。</p>","caption":""},{"image":"{{text}}A34“慧星”巡航坦克<br>1945年初，德国战场，隶属英军第11装甲师的一辆A34“慧星”巡航坦克。{{image}}imgs/uk/army/uk_army_tankcx_31.jpg{{text}}A34“慧星”巡航坦克（南非博物馆）{{image}}imgs/uk/army/uk_army_tankcx_32.jpg{{text}}A34“慧星”巡航坦克（图片）{{image}}imgs/uk/army/uk_army_tankcx_33.jpg","description":"<h6>A34“慧星”巡航坦克</h6><p>“慧星”巡航坦克车重超过35t，属于较重的中型坦克；它的车身与炮塔都使用了焊接技术，其正面装甲厚度也达到了102mm；基本上能抵挡德军大部分反坦克炮火的攻击。该坦克安装了77mm火炮（实际口径为76.2mm)，在使用脱壳装甲弹的情况下，能够在500m距离将具有30度倾角的209mm装甲射穿。因此具备了与德军重型坦克对抗的能力。</p><p>第一批“慧星”巡航坦克在1944年12月装备英军装甲部队，一直到二战结束。并在战后继续使用。</p><p>坦克参数为：</p><p>车长：7.65m，车宽：3.05m, 车高：2.68m，车重：约36.0t，乘员：5人；</p><p>最高车速：47km/h，最大行程：198km；</p><p>装甲厚度：25-102mm；</p><p>主要武器装备：一门77mm火炮。</p><p>辅助武器有2挺7.92mm贝莎机枪。</p>","caption":""}],"part2title":"战场上的A27L、A30与A34巡航坦克","part2description":"<p>A27L“半人马座”巡航坦克大部分用作训练用，后期换装95mm榴弹炮后，被装备到海军部队中（这也是英国皇家海军使用过的几种坦克之一），参加了1944年6月的D日行动，为英军提供近距离的火力支援。</p><p>A30“挑战者”巡航坦克交货时已错过了诺曼底登陆行动，而且此时已是二战末期，大量整体性能更好的谢尔曼“莹火虫”坦克已广泛地出现在战场上，加上该型坦克数量很少，它在战场上基本是无所作为了。后来它被装备给英军的装甲侦察团使用。</p><p>A34“慧星”巡航坦克虽然也是出生在二战快结束的时候，但由于它具备了与德军重型坦克的对抗能力，因此在诺曼底登陆后，它立即装备英军参加了战斗，1944年12月，第一批“慧星”巡航坦克参加了阿登反击战，后随英军继续进军德国，在战斗中有较好的表现。</p>","part2content":[{"image":"imgs/uk/army/uk_army_tankcx_41.jpg","description":"1944年6月，一辆已登陆诺曼底海滩的“半人马座”巡航坦克，这辆坦克隶属英军第1皇家装甲团第2营“H”连。","caption":""},{"image":"imgs/uk/army/uk_army_tankcx_42.jpg","description":"1944年6月10日，一队支援前线作战的英国皇家海军陆战队的半人马座巡航坦克支援集群在诺曼底贝叶地区的一条快速路上疾驰。","caption":""},{"image":"imgs/uk/army/uk_army_tankcx_43.jpg","description":"1944年英国，坦克乘员正在对一辆半人马座巡航坦克进行清洗。","caption":""},{"image":"imgs/uk/army/uk_army_tankcx_44.jpg","description":"一辆装备75mm火炮的半人马座Ⅲ型巡航坦克。该辆坦克车体前方安装了钢铲。","caption":""},{"image":"imgs/uk/army/uk_army_tankcx_45.jpg","description":"一辆装备17磅（76.2mm口径）火炮的“挑战者”巡航坦克，坦克车长正在炮塔外用望远镜向远方观察。","caption":""},{"image":"imgs/uk/army/uk_army_tankcx_46.jpg","description":"一辆“挑战者”巡航坦克正行进在一个城镇公路上。","caption":""},{"image":"imgs/uk/army/uk_army_tankcx_47.jpg","description":"1945年欧洲战场，一队“慧星”巡航坦克正在向德军阵地进行射击，一辆坦克的车长正在用望远镜观察战果。","caption":""},{"image":"imgs/uk/army/uk_army_tankcx_48.jpg","description":"坦克乘员利用战斗空隙对一辆“慧星”巡航坦克进行维护。","caption":""},{"image":"imgs/uk/army/uk_army_tankcx_49.jpg","description":"1945年欧洲战场，一队“慧星”巡航坦克正在穿过一个刚收复的城镇，这个城镇刚刚经历一场激烈的战斗，很多建筑已在战火中变成废墟。","caption":""}]}')}});